import sqlite3, json
c = sqlite3.connect(r"C:\Users\win\.cc-switch\cc-switch.db")
rows = c.execute("SELECT id, name, settings_config FROM providers WHERE app_type='codex'").fetchall()
for pid, name, sc in rows:
    cfg = json.loads(sc)
    auth = cfg.get("auth") or {}
    key = auth.get("OPENAI_API_KEY") or (cfg.get("env") or {}).get("OPENAI_API_KEY")
    base = None
    if cfg.get("config"):
        for line in cfg["config"].splitlines():
            if "base_url" in line:
                base = line.strip(); break
    print(f"{pid}|{name}|key={'set:'+key[:8]+'...' if key else 'MISSING'}|{base or 'no config'}")
